/*
 * pm_pwm_stm32f1.c - servo (PB8 / TIM4_CH3) and passive buzzer (PB9) driver.
 *
 * PB8 and PB9 both belong to TIM4, so one timer cannot give the servo its
 * 50 Hz frame and the buzzer a few kHz at the same time. TIM4 therefore stays
 * on the servo frame (1 MHz tick, ARR 19999) and the buzzer is generated by
 * TIM3 update interrupts that toggle PB9 as a plain GPIO at 10 us resolution.
 * That keeps the servo pulse train undisturbed while the buzzer runs, and the
 * interrupt rate is only 2x the tone (2..10 kHz at 100..5000 Hz).
 */
#include "pm_pwm.h"

#include "stm32f1xx.h"

#define SERVO_TICK_HZ     1000000u
#define SERVO_PSC         ((SERVO_TICK_HZ / 1000000u) - 1u)
#define SERVO_PULSE_MIN   500u      /* SG90: 0 deg */
#define SERVO_PULSE_MAX   2500u     /* SG90: 180 deg */
#define SERVO_PULSE_MID   1500u
#define BUZ_TICK_HZ       100000u   /* 10 us phase resolution */

static uint32_t s_servo_deg10;
static uint32_t s_servo_pulse;

static uint16_t s_buz_high;
static uint16_t s_buz_low;
static uint32_t s_buz_hz;
static uint8_t  s_buz_duty;
static uint8_t  s_buz_on;
static uint8_t  s_buz_phase;       /* 1 = pin high for the current phase */

static uint32_t servo_pulse_from_deg(uint32_t deg10)
{
    uint32_t span = SERVO_PULSE_MAX - SERVO_PULSE_MIN;

    return SERVO_PULSE_MIN + ((deg10 * span) / 1800u);
}

int pm_pwm_init(void)
{
    RCC->APB2ENR |= RCC_APB2ENR_IOPBEN;
    RCC->APB1ENR |= RCC_APB1ENR_TIM3EN | RCC_APB1ENR_TIM4EN;

    /* PB8: alternate-function push-pull 50 MHz (TIM4_CH3). */
    GPIOB->CRH = (GPIOB->CRH & ~(0xFu << 0)) | (0xBu << 0);
    /* PB9: plain push-pull output 2 MHz, toggled by the TIM3 ISR. */
    GPIOB->CRH = (GPIOB->CRH & ~(0xFu << 4)) | (0x2u << 4);
    GPIOB->BRR = GPIO_BRR_BR9;

    /* TIM4: 1 MHz tick, 20 ms frame, CH3 PWM mode 1 at 1.5 ms (90 deg). */
    TIM4->CR1   = 0u;
    TIM4->PSC   = SERVO_PSC;
    TIM4->ARR   = (SERVO_TICK_HZ / 50u) - 1u;
    TIM4->CCR3  = SERVO_PULSE_MID;
    TIM4->CCMR2 = (TIM4->CCMR2 & ~(0x7u << 4)) | (0x6u << 4);  /* PWM mode 1 */
    TIM4->CCMR2 |= (0x1u << 3);                                /* OC3 preload */
    TIM4->CCER  |= TIM_CCER_CC3E;
    TIM4->EGR    = TIM_EGR_UG;
    TIM4->SR     = 0u;
    TIM4->CR1    = TIM_CR1_ARPE | TIM_CR1_CEN;

    s_servo_deg10 = 900u;
    s_servo_pulse = SERVO_PULSE_MID;

    /* TIM3: 10 us tick, stopped until the buzzer is switched on. */
    TIM3->CR1  = 0u;
    TIM3->PSC  = (72000000u / BUZ_TICK_HZ) - 1u;
    TIM3->ARR  = 999u;
    TIM3->CNT  = 0u;
    TIM3->DIER = TIM_DIER_UIE;
    TIM3->EGR  = TIM_EGR_UG;
    TIM3->SR   = 0u;

    NVIC_ClearPendingIRQ(TIM3_IRQn);
    NVIC_SetPriority(TIM3_IRQn, 3);
    NVIC_EnableIRQ(TIM3_IRQn);

    return 0;
}

int pm_pwm_servo_set(int32_t deg10)
{
    if ((deg10 < PM_PWM_SERVO_MIN_DEG10) || (deg10 > PM_PWM_SERVO_MAX_DEG10)) {
        return -1;
    }
    s_servo_deg10 = (uint32_t)deg10;
    s_servo_pulse = servo_pulse_from_deg(s_servo_deg10);
    TIM4->CCR3    = s_servo_pulse;
    return 0;
}

uint32_t pm_pwm_servo_pulse_us(void)
{
    return s_servo_pulse;
}

int32_t pm_pwm_servo_deg10(void)
{
    return (int32_t)s_servo_deg10;
}

int pm_pwm_buzzer_set(uint32_t hz, uint8_t duty_pct)
{
    uint32_t period;
    uint32_t high;

    if ((hz < PM_PWM_BUZ_MIN_HZ) || (hz > PM_PWM_BUZ_MAX_HZ) ||
        (duty_pct < 1u) || (duty_pct > 99u)) {
        return -1;
    }
    period = BUZ_TICK_HZ / hz;
    if (period < 4u) {
        period = 4u;
    }
    high = (period * duty_pct) / 100u;
    if (high == 0u) {
        high = 1u;
    }
    if (high >= period) {
        high = period - 1u;
    }

    s_buz_high = (uint16_t)high;
    s_buz_low  = (uint16_t)(period - high);
    s_buz_hz   = hz;
    s_buz_duty = duty_pct;

    TIM3->CR1  = 0u;
    TIM3->CNT  = 0u;
    TIM3->ARR  = (uint16_t)(s_buz_high - 1u);
    TIM3->SR   = 0u;
    s_buz_phase = 1u;
    s_buz_on    = 1u;
    GPIOB->BSRR = GPIO_BSRR_BS9;
    TIM3->CR1   = TIM_CR1_CEN;
    return 0;
}

void pm_pwm_buzzer_off(void)
{
    TIM3->CR1  = 0u;
    TIM3->SR   = 0u;
    s_buz_on   = 0u;
    s_buz_phase = 0u;
    GPIOB->BRR = GPIO_BRR_BR9;
}

uint32_t pm_pwm_buzzer_hz(void)
{
    uint32_t period = (uint32_t)s_buz_high + (uint32_t)s_buz_low;

    return (period == 0u) ? 0u : (BUZ_TICK_HZ / period);
}

uint8_t pm_pwm_buzzer_duty(void)
{
    return s_buz_duty;
}

int pm_pwm_buzzer_on(void)
{
    return (int)s_buz_on;
}

void TIM3_IRQHandler(void)
{
    if ((TIM3->SR & TIM_SR_UIF) == 0u) {
        return;
    }
    TIM3->SR = ~TIM_SR_UIF;

    if (s_buz_phase != 0u) {
        GPIOB->BRR  = GPIO_BRR_BR9;
        TIM3->ARR   = (uint16_t)(s_buz_low - 1u);
        s_buz_phase = 0u;
    } else {
        GPIOB->BSRR = GPIO_BSRR_BS9;
        TIM3->ARR   = (uint16_t)(s_buz_high - 1u);
        s_buz_phase = 1u;
    }
}
